#include "Employees/FoundrylineEmployeeTypes.h"
#include "Production/FoundrylineFactorySimulation.h"
#include "Production/FoundrylineWorkZoneLayout.h"
using R=EFoundrylineEmployeeRole;using A=EFoundrylineEmployeeActivity;using W=EFoundrylineEmployeeWait;
const TCHAR* FFoundrylineEmployeeRoster::RoleName(R V){switch(V){case R::Operator:return TEXT("Machine operator");case R::Welder:return TEXT("Welder");case R::ForkliftDriver:return TEXT("Forklift driver");default:return TEXT("Unassigned");}}
const TCHAR* FFoundrylineEmployeeRoster::ActivityName(A V){switch(V){case A::Walking:return TEXT("Walking");case A::Waiting:return TEXT("Waiting");case A::Operating:return TEXT("Operating");case A::Welding:return TEXT("Welding");case A::Driving:return TEXT("Driving");case A::Handling:return TEXT("Handling freight");case A::Paused:return TEXT("Paused");default:return TEXT("Idle");}}
const TCHAR* FFoundrylineEmployeeRoster::WaitName(W V){switch(V){case W::Unassigned:return TEXT("Unassigned");case W::NoRoute:return TEXT("No pedestrian route");case W::Traffic:return TEXT("Yielding to traffic");case W::Materials:return TEXT("Waiting for material");case W::OutputFull:return TEXT("Output full");case W::Paused:return TEXT("Plant paused");default:return TEXT("");}}
TArray<FFoundrylineEmployeeRecord> FFoundrylineEmployeeRoster::Build(const FFoundrylineFactoryState& S){
 TArray<FFoundrylineEmployeeRecord> Out;auto Add=[&](int Id,R Role,int Assignment)->FFoundrylineEmployeeRecord&{auto& E=Out.AddDefaulted_GetRef();E.Id=Id;E.Role=Role;E.Assignment=Assignment;E.CompanyId=S.CompanyId;E.PlantId=S.PlantId;E.Key=S.CompanyId.ToString()+TEXT("/")+S.PlantId.ToString()+TEXT("/")+FString::FromInt(Id);E.Label=FString::Printf(TEXT("%s %d"),RoleName(Role),Id);return E;};
 for(const auto& O:S.Operators){auto& E=Add(O.Id,O.Machine?R::Operator:R::Unassigned,O.Machine);E.Label=O.DisplayName;E.Position=O.Position;E.Home=O.Home;E.WorkPoint=O.WorkPoint;E.Path=O.Path;E.Yaw=O.Yaw;E.Speed=O.Speed;E.Distance=O.Distance;E.Activity=O.Activity;E.Wait=O.Wait;E.bMoving=O.Speed>.1;const auto* M=S.Machines.FindByPredicate([&](const auto& V){return V.Id==O.Machine;});E.bWorking=S.Running&&M&&M->Enabled&&M->Remaining>0&&FVector::Dist2D(O.Position,O.WorkPoint)<=1;if(E.bWorking){E.Activity=A::Operating;E.Wait=W::None;E.WorkPhase=M->Duration>0?1-M->Remaining/M->Duration:0;}}
 for(const auto& V:S.Walkers){auto& E=Add(V.Id,V.Zone?R::Welder:R::Unassigned,V.Zone);E.Label=V.DisplayName;E.Position=V.Position;E.Home=V.Home;E.Path=V.Path;E.Yaw=V.Yaw;E.Speed=V.Speed;E.Distance=V.Distance;const auto* Z=S.Zones.FindByPredicate([&](const auto& X){return X.Id==V.Zone;});E.WorkPoint=Z?FFoundrylineWorkZoneLayout::WorkPoint(*Z):V.Home;const bool Arrived=Z&&Z->Ordered&&FVector::Dist2D(V.Position,E.WorkPoint)<=1;E.bMoving=V.Speed>.1;E.bWorking=S.Running&&Z&&Arrived&&Z->ActiveStep>=0;E.Activity=E.bWorking?(Z->ActiveStep==5?A::Operating:A::Welding):E.bMoving?A::Walking:V.Waiting||Z&&Z->Ordered&&!Arrived?A::Waiting:A::Idle;E.Wait=!V.Zone?W::Unassigned:V.Waiting?W::Traffic:Z&&!Z->Ordered?W::None:!Arrived&&V.Path.IsEmpty()?W::NoRoute:Arrived&&!E.bWorking?W::Materials:W::None;if(E.bWorking){E.WorkPhase=FMath::Fmod(Z->Work,1.f);E.Yaw=(FFoundrylineWorkZoneLayout::WeldPoint(*Z)-E.WorkPoint).Rotation().Yaw;}}
 for(const auto& D:S.Drivers)if(D.EmployeeId){auto& E=Add(D.EmployeeId,R::ForkliftDriver,D.Id);E.Label=D.DisplayName;E.VehicleId=D.Id;E.Position=D.Position;E.Home=D.Parking;E.WorkPoint=D.Parking;E.Path=D.Path;E.Yaw=D.Yaw;E.Distance=D.Distance;E.bSeated=true;const auto* J=S.Jobs.FindByPredicate([&](const auto& V){return V.Id==D.Job;});if(J)E.WorkPoint=J->Phase<3?J->Pickup:J->Drop;E.bMoving=!D.Waiting&&D.Path.Num()>1&&D.Distance<FFoundrylineFactorySimulation::Length(D.Path);E.Speed=E.bMoving?150:0;E.bWorking=S.Running&&J;E.Activity=D.Waiting?A::Waiting:E.bMoving?A::Driving:J&&(J->Phase==2||J->Phase==4)?A::Handling:A::Idle;E.Wait=!D.Route?W::NoRoute:D.Waiting?W::Traffic:W::None;if(J)E.WorkPhase=FMath::Clamp(1-J->Handling/2,0.f,1.f);}
 for(const auto& D:S.UnassignedEmployees){auto& E=Add(D.Id,R::Unassigned,0);E.Label=D.DisplayName;E.Position=D.Position;E.Home=E.WorkPoint=D.Home;E.Yaw=D.Yaw;E.Wait=W::Unassigned;}
 for(auto& E:Out){E.CurrentJob=TEXT("No job assigned");if(E.Role==R::Operator){const auto* M=S.Machines.FindByPredicate([&](const auto& V){return V.Id==E.Assignment;});if(M)E.CurrentJob=M->Remaining>0?FString::Printf(TEXT("%s / %s"),FFoundrylineFactoryCatalog::Part(M->Making).Name,M->Enabled?TEXT("In progress"):TEXT("Machine paused")):!M->Enabled?TEXT("Machine paused"):M->Auto?TEXT("Automatic production / awaiting demand"):M->BatchRemaining>0||M->HasQueuedProgram?FString::Printf(TEXT("%s / Waiting to process"),FFoundrylineFactoryCatalog::Part(M->Making).Name):TEXT("Machine has no active batch");}else if(E.Role==R::ForkliftDriver){const auto* D=S.Drivers.FindByPredicate([&](const auto& V){return V.Id==E.VehicleId;});const auto* J=D?S.Jobs.FindByPredicate([&](const auto& V){return V.Id==D->Job;}):nullptr;E.CurrentJob=J?FString::Printf(TEXT("%s %d %s"),J->Phase<3?TEXT("Collect"):TEXT("Deliver"),J->Quantity,FFoundrylineFactoryCatalog::Part(J->Part).Name):D&&FVector::Dist2D(D->Position,D->Parking)>20?TEXT("Returning to parking"):TEXT("Waiting for a freight or supply task");}else if(E.Role==R::Welder){const auto* Z=S.Zones.FindByPredicate([&](const auto& V){return V.Id==E.Assignment;});if(Z)E.CurrentJob=Z->CompletedMask==63?TEXT("Product complete / awaiting pickup"):Z->ActiveStep>=0?FString::Printf(TEXT("Tanker / %s"),FFoundrylineFactoryCatalog::TankerSteps()[Z->ActiveStep].Name):Z->Ordered?TEXT("Tanker / Waiting for parts"):TEXT("Welding station / No product order");}}
 if(!S.Running)for(auto& E:Out){E.Activity=A::Paused;E.Wait=W::Paused;E.Speed=0;E.bMoving=E.bWorking=false;}return Out;
}
